using System;
using System.IO;
using System.Linq;
using System.Drawing;
using System.Diagnostics;
using System.Threading.Tasks;
using System.Windows.Forms;
using RoomManager;
class GuiSmoke {
 [System.Runtime.InteropServices.DllImport("user32.dll",CharSet=System.Runtime.InteropServices.CharSet.Unicode)] static extern IntPtr FindWindowEx(IntPtr parent,IntPtr after,string cls,string title);
 [System.Runtime.InteropServices.DllImport("user32.dll")] static extern uint GetWindowThreadProcessId(IntPtr h,out uint pid);
 [System.Runtime.InteropServices.DllImport("user32.dll")] static extern bool PostMessage(IntPtr h,uint message,IntPtr w,IntPtr l);
 static int checks;static string output;
 static void Assert(bool value,string label){if(!value)throw new Exception(label);checks++;Console.WriteLine("PASS "+label);}
 static async Task Until(Func<bool> condition,string label){for(int i=0;i<120&&!condition();i++)await Task.Delay(100);Assert(condition(),label);}
 static void Screenshot(MainForm f,string name){f.Activate();f.Refresh();using(var b=new Bitmap(f.Width,f.Height)){f.DrawToBitmap(b,new Rectangle(0,0,b.Width,b.Height));b.Save(Path.Combine(output,name+".png"));}}
 static Button FindButton(Control c,string title){foreach(Control child in c.Controls){if(child is Button&&child.Text==title)return (Button)child;var found=FindButton(child,title);if(found!=null)return found;}return null;}
 [STAThread]static int Main(string[] args){output=args[2];int exit=0;Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);var form=new MainForm(new Settings(Path.Combine(output,"gui-settings")));form.StartPosition=FormStartPosition.CenterScreen;form.Shown+=async(s,e)=>{try{
  Assert(form.Visible&&form.IsHandleCreated,"真实 WinForms 窗口创建");Assert(!form.Submit.Enabled,"未连接禁止提交");Screenshot(form,"gui-disconnected");
  form.Address.Text=args[0];form.Account.Text="kp";form.Password.Text=args[1];form.Connect.PerformClick();await Until(()=>form.Submit.Enabled,"原生连接按钮登录并收到 WS/admin");Assert(form.Password.Text=="","登录后清空密码输入");form.Collection.SelectedItem="entities";await Task.Delay(600);Assert(form.Items.Items.Count>0,"实体列表显示");
  int index=-1;for(int i=0;i<form.Items.Items.Count;i++)if(form.Items.Items[i].ToString().StartsWith("actor-player1 "))index=i;Assert(index>=0,"定位角色");form.Items.SelectedIndex=index;form.Operation.SelectedItem="entity.patch";form.SetField("name","界面修改：中文与长名称验收 1234567890");form.Submit.PerformClick();await Task.Delay(1200);
  using(var observer=new ApiClient(args[0])){await observer.Login("kp",args[1]);await Until(()=>observer.Connected,"独立会话验证 GUI 写入");Assert(J.S(J.Get(J.Get(observer.View,"entities"),"actor-player1"),"name").StartsWith("界面修改"),"GUI 表单真实提交成功");
   form.Collection.SelectedItem="entities";await Task.Delay(600);for(int i=0;i<form.Items.Items.Count;i++)if(form.Items.Items[i].ToString().StartsWith("actor-player1 "))form.Items.SelectedIndex=i;form.Controls.Find("field_name",true).First().Focus();Assert(form.Controls.Find("field_name",true).First().Focused,"字段可获得键盘焦点");form.SetField("name","保留冲突草稿");var v=observer.View;await observer.Send(observer.Envelope("entity.patch",J.Obj("id","actor-player1","name","其他管理器先修改"),J.Obj("actor-player1",J.Get(J.Get(J.Get(v,"entities"),"actor-player1"),"viewToken"))));await Task.Delay(1000);form.Submit.PerformClick();await Task.Delay(700);var input=form.Controls.Find("field_name",true).First();Assert(input.Text=="保留冲突草稿","冲突后保留草稿");Assert(J.S(J.Get(J.Get(observer.View,"entities"),"actor-player1"),"name")=="其他管理器先修改","冲突不会覆盖先提交者");typeof(MainForm).GetField("uncertain",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic).SetValue(form,true);form.SetField("name","未知结果时禁止新提交");await form.Send();await Task.Delay(350);Assert(J.S(J.Get(J.Get(observer.View,"entities"),"actor-player1"),"name")=="其他管理器先修改","结果未知时禁止新 commandId 提交");typeof(MainForm).GetField("uncertain",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic).SetValue(form,false);form.SetField("name","保留冲突草稿");Screenshot(form,"gui-conflict");FindButton(form,"比较最新值").PerformClick();Assert(form.Detail.Text.Contains("其他管理器先修改")&&form.Detail.Text.Contains("保留冲突草稿"),"冲突三方比较");FindButton(form,"关注选中对象/路径").PerformClick();form.Collection.SelectedItem="关注";await Task.Delay(200);Assert(form.Items.Items.Count==1,"新增对象关注");form.Items.SelectedIndex=0;FindButton(form,"启用/禁用关注").PerformClick();Assert(File.ReadAllText(Path.Combine(output,"gui-settings/settings.json")).Contains("false"),"禁用关注持久保存");form.Items.SelectedIndex=0;FindButton(form,"删除关注").PerformClick();Assert(form.Items.Items.Count==0,"删除关注");
   form.Collection.SelectedItem="观察到的变化";await Task.Delay(600);Assert(form.Items.Items.Count>0&&!form.Submit.Enabled,"观察页有实际样本差异且禁止编辑");form.Items.SelectedIndex=form.Items.Items.Count-1;Screenshot(form,"gui-observation");
  }
  form.Collection.SelectedItem="概览";form.Operation.SelectedItem="room.status";form.SetField("status","paused");bool confirmSeen=false;var dismiss=new Timer {Interval=300};dismiss.Tick+=(sender,eventArgs)=>{IntPtr dialog=IntPtr.Zero;while((dialog=FindWindowEx(IntPtr.Zero,dialog,null,"确认提交"))!=IntPtr.Zero){uint pid;GetWindowThreadProcessId(dialog,out pid);if(pid==(uint)Process.GetCurrentProcess().Id){confirmSeen=true;dismiss.Stop();PostMessage(dialog,0x111,(IntPtr)2,IntPtr.Zero);break;}}};dismiss.Start();await form.Send();dismiss.Dispose();Assert(confirmSeen,"真实确认对话框已出现");using(var verify=new ApiClient(args[0])){await verify.Login("kp",args[1]);await Until(()=>verify.Connected,"确认框取消后的连接验证");Assert(J.S(verify.View,"status")=="active","危险操作原生确认框可取消且未提交");}
  form.Size=new Size(1050,700);form.Scale(new SizeF(1.25f,1.25f));await Task.Delay(300);Assert(form.Width>=1000&&form.Height>=650,"125% 布局缩放及最小窗口");Screenshot(form,"gui-scale125");
  var flags=System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic;((Timer)typeof(MainForm).GetField("timer",flags).GetValue(form)).Stop();var large=J.D(J.Clone(typeof(MainForm).GetField("current",flags).GetValue(form)));var entities=J.Obj();for(int n=0;n<3000;n++)entities["large-"+n]=J.Obj("instanceId","large-"+n,"name",new string('中',180),"numbers",J.Obj("hp",10));large["entities"]=entities;typeof(MainForm).GetField("current",flags).SetValue(form,large);var latency=Stopwatch.StartNew();form.Collection.SelectedItem="entities";latency.Stop();Assert(form.Items.Items.Count==500,"大列表按 500 条本地分段呈现");Assert(latency.ElapsedMilliseconds<3000,"约 2 MiB 大列表响应小于 3 秒");File.WriteAllText(Path.Combine(output,"gui-performance.json"),J.Pretty(J.Obj("objects",3000,"utf8Bytes",System.Text.Encoding.UTF8.GetByteCount(J.Text(entities)),"renderMs",latency.ElapsedMilliseconds)));Screenshot(form,"gui-large-list");
  form.Connect.PerformClick();await Until(()=>!form.Submit.Enabled&&form.Items.Items.Count==0,"断开清理数据与编辑草稿");Assert(form.Detail.Text=="","断开不残留敏感详情");
  File.WriteAllText(Path.Combine(output,"gui.json"),J.Pretty(J.Obj("passed",checks,"failed",0,"windowShown",true,"dpi",form.CreateGraphics().DpiX,"scaledLayout",1.25,"screenshots",new[]{"gui-disconnected.png","gui-conflict.png","gui-observation.png","gui-scale125.png"})));
 }catch(Exception ex){exit=1;Console.WriteLine(ex);Screenshot(form,"gui-failure");File.WriteAllText(Path.Combine(output,"gui.json"),J.Pretty(J.Obj("passed",checks,"failed",1,"error",ex.ToString())));}finally{form.Close();}};Application.Run(form);return exit;}
}
